function transform(ctx) {
  var auth_tag = String(Math.floor(now_ms()));
  var key = [];
  for (var i = 0; i < 256; i++) { key.push(auth_tag.charCodeAt(i % auth_tag.length)); }
  var sbox = [];
  for (var i = 0; i < 256; i++) { sbox[i] = i; }
  var j = 0;
  for (var i = 0; i < 256; i++) { j = (j + sbox[i] + key[i]) % 256; var t = sbox[i]; sbox[i] = sbox[j]; sbox[j] = t; }
  var text = ctx.password || "";
  var a = 0, b = 0, out = "";
  for (var i = 0; i < text.length; i++) {
    a = (a + 1) % 256;
    b = (b + sbox[a]) % 256;
    var t2 = sbox[a]; sbox[a] = sbox[b]; sbox[b] = t2;
    var c = (sbox[a] + sbox[b]) % 256;
    var x = text.charCodeAt(i) ^ sbox[c];
    out += (x < 16 ? "0" : "") + x.toString(16);
  }
  return { auth_tag: auth_tag, rc4_pwd: out, form_username: url_encode(ctx.username || "") };
}
